data.query:
query GetInventory($where: InventoryWhereInput!) {
  inventory(where: $where) {
    total
    edges {
      node {
        id
        serialNumber
        active
        inventoryStatusId
        quantity { value unitId }
        mrbHoldStatus
        mrbCaseId
        product { id code }
        storageUnit { id code }
        lot { id number }
      }
    }
  }
}

data.responseTransform:
{
  "success": false,
  "severity": "error",
  "title": "Inventory Not Found",
  "message": "No inventory record found for the provided ID.",
  "data": { "inventoryId": $state.context.INPUT.inventoryId }
}

{
  "success": false,
  "severity": "error",
  "title": "Inventory Inactive",
  "message": "This inventory record has been soft-deleted and cannot be adjusted.",
  "data": { "serialNumber": $state.context.INV.serialNumber }
}

{
  "success": false,
  "severity": "error",
  "title": "Inventory Retired",
  "message": "This inventory has been retired and cannot be adjusted.",
  "data": { "serialNumber": $state.context.INV.serialNumber }
}

{
  "success": false,
  "severity": "error",
  "title": "MRB Quality Hold!",
  "message": "This inventory is on MRB quality hold (" & $state.context.INV.mrbHoldStatus & ") and cannot be adjusted directly. Use the MRB disposition process. Case ID: " & $state.context.INV.mrbCaseId,
  "data": {
    "serialNumber": $state.context.INV.serialNumber,
    "mrbHoldStatus": $state.context.INV.mrbHoldStatus,
    "mrbCaseId": $state.context.INV.mrbCaseId
  }
}

data.query:
query GetAdjustment($where: AdjustmentWhereInput!) {
  adjustment(where: $where) {
    total
    edges {
      node {
        id
        name
        usable
        tolerance
      }
    }
  }
}

data.responseTransform:
{
  "success": false,
  "severity": "error",
  "title": "Invalid Adjustment Type",
  "message": "The adjustment type provided does not exist or is not usable.",
  "data": { "adjustmentId": $state.context.INPUT.adjustmentId }
}

data.mutation:
mutation AdjustInventory($payload: [InventoryUpdatePayloadInput!]!) {
  updateInventory(payload: $payload) {
    id
    serialNumber
    quantity { value unitId }
    lastAdjustmentId
    lastTransactionTypeId
  }
}

data.responseTransform:
{
  "success": true,
  "severity": "success",
  "title": "MRB Scrap Complete",
  "message": "Inventory adjusted to zero. Update the MRB Scrap action item in QCS to complete the disposition. Case ID: " & $state.context.INV.mrbCaseId,
  "data": {
    "serialNumber": $state.context.INV.serialNumber,
    "mrbCaseId": $state.context.INV.mrbCaseId,
    "newQuantity": $state.context.INPUT.quantity
  }
}

